_ROOT_AWARE_CODE = ("catalog.py", "explorer.py", "vehicle_photos.py")


def _uploaded_files(repo):
    return {path: repo / Path(path).name for path in _EXISTING_FILES}


@st.cache_resource(show_spinner=False, max_entries=1)
def _load_package(repo_directory, revision):
    repo = Path(repo_directory)
    workspace = TemporaryDirectory(prefix="autoverse-recovered-")
    stage = Path(workspace.name) / "autoverse_app"
    module_name = "_autoverse_restored_" + Path(workspace.name).name.rsplit("-", 1)[-1]
    try:
        for relative, source in _uploaded_files(repo).items():
            destination = stage / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            copyfile(source, destination)

        # This embedded archive contains only the five missing release files.
        with ZipFile(BytesIO(b64decode(_SUPPLEMENT))) as archive:
            for relative in archive.namelist():
                destination = stage / relative
                destination.parent.mkdir(parents=True, exist_ok=True)
                destination.write_bytes(archive.read(relative))

        # The three modules resolve repository data relative to their own files.
        # Point their data lookups at the checkout when staging in a temp folder.
        previous = "Path(__file__).resolve().parents[1]"
        for relative in _ROOT_AWARE_CODE:
            source = stage / relative
            content = source.read_text(encoding="utf-8")
            if content.count(previous) != 1:
                raise RuntimeError(f"Unexpected repository path in {relative}")
            source.write_text(
                content.replace(previous, f"Path({str(repo)!r})", 1),
                encoding="utf-8",
            )

        spec = spec_from_file_location(
            module_name, stage / "__init__.py", submodule_search_locations=[str(stage)]
        )
        package = module_from_spec(spec)
        sys.modules[module_name] = package
        spec.loader.exec_module(package)
    except Exception:
        sys.modules.pop(module_name, None)
        workspace.cleanup()
        raise

    # Keep the stage alive for lazy imports, videos and simulator assets.
    return package, workspace


def run():
    repo = Path(__file__).resolve().parent
    uploaded = _uploaded_files(repo)
    missing = [file.name for file in uploaded.values() if not file.is_file()]
    if missing:
        st.error("복구에 필요한 파일을 저장소에서 찾을 수 없어요: " + ", ".join(missing))
        return
    revision = tuple((file.stat().st_size, file.stat().st_mtime_ns) for file in uploaded.values())
    package, _ = _load_package(str(repo), revision)
    package.run()


